def remote_run(payload, hashes):
    import base64
    import hashlib
    import json
    import os
    import subprocess
    import sys
    import tempfile
    import traceback
    import zlib
    from pathlib import Path

    out = Path("/kaggle/working")
    out.mkdir(parents=True, exist_ok=True)
    scratch = Path("/kaggle/temp")
    scratch.mkdir(parents=True, exist_ok=True)
    for option in ("OPENBLAS_NUM_THREADS", "OMP_NUM_THREADS", "MKL_NUM_THREADS"):
        os.environ[option] = "4"
    runtime = {"input_sha256": hashes}
    try:
        import torch
        torch.set_num_threads(4)
        if not torch.cuda.is_available():
            raise RuntimeError("Scale evaluation requires CUDA")
        runtime.update(device=torch.cuda.get_device_name(0), pytorch=str(torch.__version__),
                       cuda=torch.version.cuda)
        with tempfile.TemporaryDirectory(dir=scratch) as temp_dir:
            stage = Path(temp_dir)
            for name, encoded in payload.items():
                data = zlib.decompress(base64.b64decode(encoded))
                if hashlib.sha256(data).hexdigest() != hashes[name]:
                    raise ValueError(f"Bundle checksum mismatch for {name}")
                (stage / name).write_bytes(data)
            print(f"Running on {runtime['device']} with {len(hashes)} verified inputs", flush=True)
            with (out / "scale-driver.log").open("w", encoding="utf-8") as log:
                command = [sys.executable, "-u", str(stage / "run_scale.py")]
                with subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                                      cwd=out, text=True, encoding="utf-8", errors="replace") as proc:
                    for line in proc.stdout:
                        print(line, end="", flush=True)
                        log.write(line)
                        log.flush()
                    exit_code = proc.wait()
                if exit_code:
                    raise subprocess.CalledProcessError(exit_code, command)
        for side in (60, 100):
            json.loads((out / f"scale-{side}.json").read_text(encoding="utf-8"))
        runtime["status"] = "complete"
    except BaseException:
        runtime.update(status="failed", error=traceback.format_exc())
        raise
    finally:
        (out / "scale-runtime.json").write_text(json.dumps(runtime, indent=2) + "\n", encoding="utf-8")

remote_run({'looped.py': '', 'weights.py': '', 'evaluate.py': '', 'corpus.py': '', 'run_scale.py': '', 'corpus-lock.json': '', 'weights.npz': '', 'freeze.json': ''}, {'looped.py': '2bf005117aac8e0d59395a52fd4fa557d09abe46beb6074aedcee77dc4a209e1', 'weights.py': '4ad4d0c5559731614549aa379af0d4ae8bd53a813bd3d71790a41fd3b1132e5e', 'evaluate.py': '3b1bff54611a37011466a83af8155c5e1490a4b34495ff13ed9b53f8812384f2', 'corpus.py': 'fc05425c1a03d79fac8ca0ecff7bec5a022bb95524da4521f19b3dbc6eca3ab5', 'run_scale.py': 'b67df990c1f1aec7041cae1b3b19eaba5737226994c7c0456e76019dd11e50ab', 'corpus-lock.json': 'c9a2346e81a0adc06189f999ac4a01eb86ebe2b87ca72767f538d22f3027e440', 'weights.npz': '587ea013ed0a4f9d96ec5a12d0892920f63990cee028db2738e382b91a7d8350', 'freeze.json': 'fee044082c15ba965a40a17ef7f24bc213d115d74e69e528f3535c0ff2ac7f11'})
